#pragma once
// iges::dispatch — per-entity-type routing for parse, write, and evaluate.
//
// Three free functions keyed by IGES entity type number:
//   * parse_entity_dispatch    — ParamTokenizer → nlohmann::json
//   * write_entity_dispatch    — nlohmann::json → PD parameter string
//   * evaluate_entity_dispatch — nlohmann::json → (point, tangent, normal)
//
// Implementations are machine-generated by
// Evals/IGES-SDK/scripts/generate_dispatch.py.

#include "../types.hpp"
#include "../entities/entity.hpp"
#include "../parser/param_tokenizer.hpp"
#include <expected>
#include <optional>
#include <string>
#include <nlohmann/json.hpp>

namespace iges {

struct EvalResult {
    Vec3 point;
    std::optional<Vec3> tangent;  // curves only
    std::optional<Vec3> normal;   // surfaces only
};

std::expected<nlohmann::json, Diagnostic>
parse_entity_dispatch(int type, int form, ParamTokenizer& tok);

std::expected<std::string, Diagnostic>
write_entity_dispatch(int type, int form, nlohmann::json const& data);

std::expected<EvalResult, Diagnostic>
evaluate_entity_dispatch(int type, int form, nlohmann::json const& data,
                         Real t, std::optional<Real> s);

} // namespace iges
